// ELEMENTS:
// 1. Fundo pelo tom (tone: navy | blue | white) com o filete vermelho no topo
// 2. Número do caso gigante em contorno, a subir por trás, e um painel de cor a deslizar na diagonal
// 3. Medalhão de cor (vermelho, ou azul royal no tom branco) com o ícone em traço que se desenha
//    (icon: casa | euro | obras | monumento)
// 4. Eyebrow "CASO n", título (anim.text), traço vermelho e sub
// 5. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const BLUE = "#013BA9";
const TINT = "#E8EEF9";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const MIST = "#C9D3E3";
const GREY = "#5A6370";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const BACK = Easing.out(Easing.back(1.7));
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const TONES = {
  navy: { bg: NAVY, panel: BLUE, text: WHITE, muted: MIST, outline: "rgba(255,255,255,0.3)", badge: RED },
  blue: { bg: BLUE, panel: NAVY, text: WHITE, muted: TINT, outline: "rgba(255,255,255,0.35)", badge: RED },
  white: { bg: WHITE, panel: TINT, text: NAVY, muted: GREY, outline: "rgba(1,59,169,0.28)", badge: BLUE },
} as const;

const ICONS: Record<string, string> = {
  casa: "M14 60 L60 20 L106 60 M26 50 V104 H94 V50 M50 104 V76 H70 V104",
  euro: "M80 36 A30 30 0 1 0 80 84 M30 54 H72 M30 68 H66",
  obras: "M8 106 H112 M22 106 V64 L50 40 L78 64 V106 M42 106 V84 H58 V106 M94 106 V16 M94 16 H58 M94 28 L106 16 M66 16 V36 M62 36 H70",
  monumento: "M14 44 L60 16 L106 44 Z M20 52 H100 M28 52 V96 M46 52 V96 M74 52 V96 M92 52 V96 M16 96 H104 M10 106 H110",
};

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.22) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.07, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const CasoAbertura: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const T = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const tone = TONES[(String(p.tone ?? "navy") as keyof typeof TONES)] ?? TONES.navy;
  const n = String(p.n ?? "").trim();
  const icon = ICONS[String(p.icon ?? "casa")] ?? ICONS.casa;
  const sub = String(p.sub ?? "").trim();
  const title = String(anim.text ?? "").trim();

  const show = (delay: number, len = 0.7, easing = EASE): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing });
  const rise = (delay: number, dist = 26): React.CSSProperties => {
    const t = show(delay);
    return { opacity: t, transform: `translateY(${(1 - t) * dist * u}px)` };
  };
  const numIn = show(0, 1.1);
  const drift = interpolate(f, [0, T], [0, -30 * u], clamp);
  const panel = show(0, 0.9);
  const badge = show(0.25, 0.6, BACK);

  return (
    <AbsoluteFill style={{ backgroundColor: tone.bg, overflow: "hidden" }}>
      <div style={{ position: "absolute", left: -W * 0.2, top: H * 0.56, width: W * 1.4, height: H * 0.7, background: tone.panel, transform: `rotate(-8deg) translateX(${(1 - panel) * W * 1.2}px)`, transformOrigin: "left top" }} />
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "flex-start", paddingTop: 150 * u }}>
        <div style={{ fontFamily: FONTS.display, fontWeight: 800, fontSize: 760 * u, lineHeight: 0.9, color: "transparent", WebkitTextStroke: `${3 * u}px ${tone.outline}`, opacity: numIn, transform: `translateY(${(1 - numIn) * 120 * u + drift}px)` }}>{n}</div>
      </AbsoluteFill>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "flex-end", flexDirection: "column", textAlign: "center", padding: `0 ${90 * u}px ${300 * u}px`, gap: 34 * u }}>
        <div style={{ width: 220 * u, height: 220 * u, borderRadius: "50%", background: tone.badge, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${badge})`, boxShadow: "0 20px 50px rgba(0,0,0,0.3)" }}>
          <svg width={130 * u} height={130 * u} viewBox="0 0 120 120" style={{ overflow: "visible" }}>
            <path d={icon} fill="none" stroke={WHITE} strokeWidth={4} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - show(0.55, 1.1)} />
          </svg>
        </div>
        {n ? (
          <div style={{ display: "flex", alignItems: "center", gap: 18 * u, fontFamily: FONTS.body, fontWeight: 600, fontSize: 30 * u, letterSpacing: "0.32em", textTransform: "uppercase", color: tone.muted, ...rise(0.5) }}>
            <div style={{ width: 44 * u, height: 3 * u, background: RED }} />
            {`Caso ${n}`}
          </div>
        ) : null}
        <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: (title.length > 22 ? 92 : 108) * u, lineHeight: 1.08, color: tone.text, maxWidth: 900 * u, ...rise(0.7, 36) }}>{title}</div>
        <div style={{ width: show(1.1, 0.7) * 110 * u, height: 3 * u, background: RED }} />
        {sub ? <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 46 * u, lineHeight: 1.25, color: tone.muted, maxWidth: 860 * u, ...rise(1.3) }}>{sub}</div> : null}
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default CasoAbertura;
